/* Types */
export type AddColumn = {
	name: string,
	/**  As SQL: `text`, `numeric(10,2)`, `timestamp with time zone`, `public.my_enum`, `int[]`. */
	typeName: string,
	nullable: boolean,
	defaultValue: string | null,
	comment: string | null,
};

export type AddEnumValue = {
	schema: string,
	name: string,
	value: string,
	/**  `None`: at the end. */
	position: EnumPosition | null,
	ifNotExists: boolean,
};

/**  Everything about one existing column that is to change; `None` leaves it as it is. */
export type AlterColumn = {
	column: string,
	newName: string | null,
	typeName: string | null,
	/**  How to turn the old values into the new type: `col::integer`. Only with `type_name`. */
	using: string | null,
	nullable: boolean | null,
	defaultValue: DefaultChange | null,
	comment: CommentChange | null,
};

export type AlterRole = {
	name: string,
	newName: string | null,
	attributes: RoleAttributes,
	password: RolePasswordChange,
	/**
	 *  What it should be a member of afterwards, and what it was before: the difference is
	 *  granted and revoked.
	 */
	memberOf: string[],
	previousMemberOf: string[],
};

/**  What the UI receives when a command fails (ANG-8 D9). Absent details are `null`. */
export type AppError = {
	code: string,
	message: string,
	/**  SQLSTATE, e.g. `23505`. */
	pgCode: string | null,
	detail: string | null,
	hint: string | null,
	/**  1-based character offset into the submitted SQL. */
	position: number | null,
};

export type AppInfo = {
	name: string,
	version: string,
};

/**  What a committed change set did. */
export type ApplyResult = {
	updated: number,
	deleted: number,
	/**
	 *  The inserted rows as the server stored them (defaults and serials filled in), every cell
	 *  as text in table column order, in the order of `TableChanges::inserts`.
	 */
	inserted: ((string | null)[])[],
};

/**  One client connection of the server, from `pg_stat_activity`. */
export type Backend = {
	pid: number,
	database: string | null,
	user: string | null,
	application: string,
	/**  The client's address; `None` for a connection over a Unix socket. */
	client: string | null,
	/**  `active`, `idle`, `idle in transaction`, … (`None` when the role may not see it). */
	state: string | null,
	waitEventType: string | null,
	waitEvent: string | null,
	/**  How long it has been in this state: running the query while `active`, waiting otherwise. */
	stateSecs: number | null,
	/**  How long its transaction has been open. */
	transactionSecs: number | null,
	/**  The query it runs, or ran last, cut to a few thousand characters. */
	query: string,
	/**  The pids it waits for. */
	blockedBy: number[],
	/**  What it waits for when it is blocked: `ShareLock on public.orders`. */
	lockWait: string | null,
	/**  The connection the app used to ask. It can't be stopped from here. */
	isSelf: boolean,
};

export type BackupFormat = 
/**  `pg_restore` can pick tables and restore in parallel. Compressed. */
"custom" | 
/**  A SQL script, for `psql`. */
"plain" | 
/**  A folder with one file per table, restorable in parallel. */
"directory" | "tar";

export type BackupRequest = {
	/**
	 *  The folder with the PostgreSQL programs; `None`: the newest one found that is not older
	 *  than the server.
	 */
	toolsDir: string | null,
	/**  The database to back up; `None`: the one connected to. */
	database: string | null,
	/**  The file to write (for the directory format, the folder, which must not exist yet). */
	path: string,
	format: BackupFormat,
	schemaOnly: boolean,
	dataOnly: boolean,
	/**  Only these tables (`pg_dump -t`): names or patterns like `public.orders*`. */
	includeTables: string[],
	/**  Leave these tables out (`pg_dump -T`). */
	excludeTables: string[],
	/**  0 (none) to 9, for the custom and directory formats; `None`: the program's default. */
	compression: number | null,
	/**  Leave out who owns what (`--no-owner`). */
	noOwner: boolean,
};

/**
 *  What a cell is to become. Text stays text until the server casts it (`$1::text::<type>`),
 *  so a bigint above 2^53, a numeric or a jsonb document reaches the table exactly as typed.
 */
export type CellValue = { kind: "value"; text: string } | 
/**  SQL `NULL`, sent as a bound `None`. */
{ kind: "null" } | 
/**  The keyword `DEFAULT`: the column's own default (a serial, `now()`, …). */
{ kind: "default" };

export type CheckSpec = {
	name: string | null,
	expression: string,
	/**  Check new rows only; the old ones are not looked at (and can be validated later). */
	notValid: boolean,
};

export type ColorTag = "none" | "green" | "yellow" | "red";

export type ColumnIdentity = 
/**  `GENERATED ALWAYS AS IDENTITY` */
"always" | 
/**  `GENERATED BY DEFAULT AS IDENTITY` */
"byDefault";

export type ColumnInfo = {
	name: string,
	/**  1-based position in the table. */
	position: number,
	/**  As Postgres prints it: `numeric(20,6)`, `character varying(100)`, `text[]`. */
	typeName: string,
	/**  The type without length or precision (`numeric`). Edits cast to this (ANG-8 D7). */
	baseType: string,
	typeOid: number,
	nullable: boolean,
	/**  The `DEFAULT` expression as SQL text, e.g. `now()`. */
	defaultValue: string | null,
	identity: ColumnIdentity | null,
	/**  A `GENERATED ALWAYS AS (...) STORED` column: can't be written. */
	generated: boolean,
	isPrimaryKey: boolean,
	comment: string | null,
	foreignKeys: ForeignKeyRef[],
};

/**  One column of the file going to one column of the table. */
export type ColumnMap = {
	/**  The column's name in the file (see [`ImportPreview::columns`]). */
	source: string,
	/**  The column of the table it is written to. */
	column: string,
};

export type CommentChange = { kind: "set"; text: string } | 
/**  `COMMENT … IS NULL` */
{ kind: "clear" };

export type CompletionColumn = {
	name: string,
	/**  As Postgres prints it: `numeric(20,6)`. */
	typeName: string,
};

export type CompletionFunction = {
	schema: string,
	name: string,
	/**  `(p_name text DEFAULT 'world'::text) → text` */
	signature: string,
};

/**
 *  What the SQL editor needs to complete names: every table and view with its columns, and the
 *  user-defined functions, across all non-system schemas (ANG-30).
 */
export type CompletionSchema = {
	/**  `current_schemas(false)`: the schemas whose objects can be named without a prefix. */
	searchPath: string[],
	tables: CompletionTable[],
	functions: CompletionFunction[],
};

export type CompletionTable = {
	schema: string,
	name: string,
	kind: ObjectKind,
	columns: CompletionColumn[],
};

/**  A `CONCURRENTLY` statement that failed after the rest was already saved. */
export type ConcurrentFailure = {
	label: string,
	sql: string,
	error: AppError,
};

/**  Saved connection settings. The password is NOT stored here — it lives in the macOS Keychain. */
export type ConnectionConfig = {
	/**  Empty when creating a connection; the backend assigns an id. */
	id: string,
	name: string,
	host: string,
	port: number,
	user: string,
	database: string,
	sslMode: SslMode,
	color: ColorTag,
	group: string | null,
	safeMode: SafeMode,
	/**
	 *  Stop any statement that runs longer than this many milliseconds (`statement_timeout`).
	 *  `None` or `0`: no limit. Missing in files saved before ANG-31.
	 */
	statementTimeoutMs?: number | null,
	/**
	 *  True when a password is saved in the Keychain. Maintained by the backend, ignored on input.
	 *  Kept here so listing connections never has to touch the Keychain.
	 */
	hasPassword: boolean,
	/**
	 *  Reach the database through an SSH server (ANG-43). `None`: connect directly. Missing in
	 *  files saved before ANG-43.
	 */
	ssh?: SshConfig | null,
	/**
	 *  Certificate files for TLS (ANG-44). `None`: the system's trusted roots, no client
	 *  certificate. Missing in files saved before ANG-44.
	 */
	sslFiles?: SslFiles | null,
};

/**  How the open connection is doing, for the status bar (ANG-48). */
export type ConnectionHealth = {
	/**  A lost connection was found and the new one is not there yet. */
	reconnecting: boolean,
	/**  How many times a lost connection has been replaced since connecting. */
	reconnects: number,
};

/**  Result of a successful connect or connection test. */
export type ConnectionInfo = {
	/**  e.g. `16.4` */
	serverVersion: string,
	/**  Time to connect and run the first query. */
	latencyMs: number,
};

export type ConstraintInfo = {
	name: string,
	kind: ConstraintKind,
	/**
	 *  `PRIMARY KEY (id)`, `FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE`,
	 *  `CHECK ((qty > 0))`, … as the server prints it.
	 */
	definition: string,
	columns: string[],
	/**  A foreign key's target, `schema.table`. */
	references: string | null,
	deferrable: boolean,
	initiallyDeferred: boolean,
	/**  `false` for a constraint added `NOT VALID`: new rows are checked, old ones are not. */
	validated: boolean,
	comment: string | null,
};

export type ConstraintKind = "primaryKey" | "foreignKey" | "unique" | "check" | "exclusion";

export type CreateDatabase = {
	name: string,
	/**  `None`: the role that is connected. */
	owner: string | null,
	/**  `None`: `template1`. */
	template: string | null,
	/**  `UTF8`, `LATIN1`, …; `None`: the template's. */
	encoding: string | null,
};

export type CreateIndex = {
	/**  `None`: the server picks one. */
	name: string | null,
	method: IndexMethod,
	columns: IndexColumn[],
	unique: boolean,
	/**  A partial index: only rows where this is true are in it. */
	whereClause: string | null,
	/**  Does not lock writes while it builds, but can't run inside the transaction. */
	concurrently: boolean,
};

export type CreateRole = {
	name: string,
	attributes: RoleAttributes,
	/**  `None`: no password (the role can't log in with one). */
	password: string | null,
	memberOf: string[],
};

export type CreateSchema = {
	name: string,
	owner: string | null,
};

export type CreateTable = {
	schema: string,
	name: string,
	comment: string | null,
	columns: NewTableColumn[],
};

export type CsvOptions = {
	/**  One character: `,` `;` tab `|` … */
	delimiter: string,
	/**  One character, doubled inside a value: `"` or `'`. */
	quote: string,
	header: boolean,
	/**  What `NULL` is written as. Blank: nothing (an empty text is then quoted, to tell them apart). */
	nullText: string,
};

export type DatabaseInfo = {
	name: string,
	/**  The database this session is connected to. */
	isCurrent: boolean,
};

/**  What the "new database" form offers. */
export type DatabaseOptions = {
	roles: string[],
	/**  Every database, templates included. */
	templates: string[],
	encodings: string[],
	/**  The role that is connected. */
	currentRole: string,
};

/**  One entry of the sidebar tree. */
export type DbObject = {
	/**  `pg_class` / `pg_proc` / `pg_type` OID. Overloaded functions share a name, not an OID. */
	oid: number,
	schema: string,
	name: string,
	kind: ObjectKind,
	/**
	 *  From `pg_class.reltuples`: an estimate that is stale until the next ANALYZE.
	 *  `None` for views, sequences, functions, and tables never analyzed.
	 */
	rowEstimate: number | null,
	/**  Functions: `(arguments) → result type`. */
	detail: string | null,
};

export type DefaultChange = 
/**  `SET DEFAULT expression` */
{ kind: "set"; expression: string } | 
/**  `DROP DEFAULT` */
{ kind: "drop" };

/**  One line of `pg_default_acl`: what new objects made by `role` start out with. */
export type DefaultPrivilege = {
	role: string,
	/**  `None`: in every schema. */
	schema: string | null,
	/**  `tables`, `sequences`, `functions`, `types` or `schemas`. */
	objectType: string,
	/**  `None`: PUBLIC. */
	grantee: string | null,
	privileges: string[],
};

export type DropColumn = {
	column: string,
	cascade: boolean,
};

export type DropConstraint = {
	name: string,
	cascade: boolean,
};

export type DropDatabase = {
	name: string,
	/**  Disconnect whoever is using it first (`WITH (FORCE)`, PostgreSQL 13 and later). */
	force: boolean,
};

export type DropIndex = {
	name: string,
	concurrently: boolean,
};

export type DropObject = {
	objectKind: ObjectKind,
	schema: string,
	name: string,
	/**  Also drop what depends on it (views, foreign keys of other tables). */
	cascade: boolean,
};

export type DropRole = {
	name: string,
	/**
	 *  Give what the role owns to this role first (`REASSIGN OWNED`, then `DROP OWNED`: in this
	 *  database only). Without it PostgreSQL refuses while the role owns anything.
	 */
	reassignTo: string | null,
};

export type DropSchema = {
	name: string,
	/**  Also drop everything in it. */
	cascade: boolean,
};

export type EnumPosition = {
	/**  `true`: before `existing`; `false`: after it. */
	before: boolean,
	existing: string,
};

/**  What `EXPLAIN` gave back. */
export type ExplainOutcome = 
/**  The plan as the server wrote it: `EXPLAIN (FORMAT JSON …)`'s single value. */
{ kind: "plan"; json: string } | { kind: "error"; error: AppError; 
/**  Where the server pointed, as an offset into the submitted text (UTF-16 units). */
offset: number | null };

export type ExplainRun = {
	outcome: ExplainOutcome,
	durationMs: number,
	/**  `EXPLAIN ANALYZE`: the statement really ran. */
	analyzed: boolean,
	/**  What the explained statement does to the database. */
	statementKind: StatementKind,
	/**  `UPDATE`, `SELECT`, … */
	command: string,
	/**
	 *  The statement ran inside a transaction (or savepoint) that was rolled back afterwards, so
	 *  whatever it changed is undone. Sequences and other non-transactional effects are not.
	 */
	rolledBack: boolean,
};

export type ExportFormat = {
	kind: "csv",
} & CsvOptions | ({ kind: "json"; 
/**  One object per line instead of one array. */
ndjson: boolean }) & { batchSize?: never } | 
/**  `INSERT` statements. */
({ kind: "sql"; 
/**  Rows per statement. Clamped to 1..=10000. */
batchSize: number }) & { ndjson?: never } | ({ kind: "markdown" }) & { batchSize?: never; ndjson?: never };

export type ExportRequest = {
	source: ExportSource,
	format: ExportFormat,
	/**  The file to write; for several tables, the folder to write the files in. */
	path: string,
};

/**  What to export. */
export type ExportSource = 
/**  One table or view, with the filters and sort of the grid it is exported from. */
{
	kind: "table",
} & TableExport | 
/**  The rows a query returns. It is run again for the export, in a read-only transaction. */
{
	kind: "query",
} & QueryExport | 
/**  Several tables, one file each, into a folder. */
{ kind: "tables"; tables: TableRef[] };

export type ExportState = "running" | "done" | "failed" | "cancelled";

export type ExportStatus = {
	state: ExportState,
	/**  Rows written so far (all files). */
	rows: number | null,
	/**  Bytes written so far. */
	bytes: number | null,
	/**
	 *  The planner's guess of how many rows there will be, when it has one (a table without
	 *  filters). Only for the progress bar.
	 */
	estimatedRows: number | null,
	/**  The table or file being written. */
	current: string | null,
	/**  The files written (complete ones). */
	files: string[],
	error: AppError | null,
};

/**
 *  One condition of the filter bar. `values` holds what the operator needs: none for
 *  `isNull` / `isNotNull`, two for `between`, one or more for `in`, exactly one otherwise.
 *  Values are always text; the server casts them to the column's type.
 */
export type Filter = {
	column: string,
	op: FilterOp,
	values: string[],
};

export type FilterOp = "eq" | "ne" | "lt" | "gt" | "le" | "ge" | "like" | "iLike" | "in" | "isNull" | "isNotNull" | "between";

/**  A column of this table that points at a column of another table. */
export type ForeignKeyRef = {
	constraint: string,
	schema: string,
	table: string,
	column: string,
};

export type ForeignKeySpec = {
	name: string | null,
	columns: string[],
	refSchema: string,
	refTable: string,
	refColumns: string[],
	onDelete: RefAction,
	onUpdate: RefAction,
	notValid: boolean,
};

export type GeneratedKind = 
/**  `GENERATED ALWAYS AS (…) STORED` */
"stored" | 
/**  `GENERATED ALWAYS AS (…) VIRTUAL` (PostgreSQL 18) */
"virtual";

/**  A statement that was run, newest first in listings. */
export type HistoryEntry = {
	id: number,
	connectionId: string,
	sql: string,
	/**  Unix time in milliseconds. */
	ranAt: number | null,
	durationMs: number,
	/**  The statement succeeded. */
	ok: boolean,
};

/**
 *  One connection to import, with the secrets the person typed for it. It carries the settings
 *  that were shown, not a place in the file: what is saved is exactly what was on screen, even if
 *  the file changed since it was read.
 */
export type ImportEntry = {
	connection: SharedConnection,
	password: string | null,
	sshSecret: string | null,
	sslKeySecret: string | null,
	sshJumpSecret?: string | null,
};

export type ImportFormat = { kind: "csv"; 
/**  One ASCII character: `,` `;` tab `|`. */
delimiter: string; 
/**  One ASCII character: `"` or `'`. */
quote: string; 
/**  The first row has the column names. */
header: boolean; 
/**  What `NULL` is written as in the file. Blank: an empty field. */
nullText: string } | 
/**  An array of objects, or one object per line (told apart by the first character). */
{ kind: "json" };

export type ImportPreview = {
	/**  The columns of the file: the header, or `column_1`, … without one; for JSON the keys. */
	columns: string[],
	/**  The first rows, one cell per column; `None` for `NULL`. */
	rows: ((string | null)[])[],
	/**  A type for each column that fits what the first thousand rows hold (for a new table). */
	suggestedTypes: string[],
	fileBytes: number | null,
	/**  The file has more rows than the preview shows. */
	moreRows: boolean,
};

export type ImportRequest = {
	path: string,
	format: ImportFormat,
	target: ImportTarget,
	onError: OnError,
};

export type ImportState = "running" | "done" | "failed" | "cancelled";

export type ImportStatus = {
	state: ImportState,
	/**  Rows read from the file so far. */
	rowsRead: number | null,
	/**  Rows written (kept only if the import completes). */
	rowsWritten: number | null,
	/**  Rows left out because they could not be written (`OnError::Skip`). */
	rowsSkipped: number | null,
	bytesRead: number | null,
	bytesTotal: number | null,
	/**  The first rows that failed, with the line and the reason. */
	errors: RowError[],
	/**  There were more failed rows than `errors` holds. */
	moreErrors: boolean,
	/**  What stopped the import as a whole, if it did not finish. */
	error: AppError | null,
	/**  The table written to (`schema.table`). */
	table: string | null,
};

export type ImportTarget = 
/**
 *  A table that exists. File columns that are not mapped are left out; table columns that
 *  are not mapped get their defaults.
 */
{ kind: "existing"; schema: string; table: string; mapping: ColumnMap[]; 
/**  Empty the table first (in the same transaction, so a failed import keeps its rows). */
truncate: boolean } | 
/**  Make the table from the file first. */
{ kind: "new"; schema: string; table: string; columns: NewColumn[] };

/**
 *  A foreign key of another table that points at this one ("referenced by"). The two column
 *  lists are in constraint order: `columns[i]` of `schema.table` references `referenced_columns[i]`
 *  of the table asked about.
 */
export type IncomingForeignKey = {
	constraint: string,
	schema: string,
	table: string,
	columns: string[],
	referencedColumns: string[],
};

/**  One thing an index is on: a column, or an expression like `lower(email)`. */
export type IndexColumn = {
	text: string,
	isExpression: boolean,
	descending: boolean,
};

export type IndexInfo = {
	name: string,
	/**  `CREATE INDEX …` as the server prints it. */
	definition: string,
	/**  The indexed columns or expressions, in order (included columns are not listed). */
	columns: string[],
	/**  `btree`, `gin`, … */
	method: string,
	unique: boolean,
	primary: boolean,
	/**  `false` while a `CREATE INDEX CONCURRENTLY` is unfinished or after it failed. */
	valid: boolean,
	/**  Has a `WHERE`. */
	partial: boolean,
	sizeBytes: number | null,
	/**  The constraint this index backs (primary key, unique or exclusion), if any. */
	constraint: string | null,
	comment: string | null,
};

export type IndexMethod = "btree" | "hash" | "gin" | "gist" | "spgist" | "brin";

export type KeySpec = {
	name: string | null,
	columns: string[],
};

/**  How many rows match, counting at most `cap` of them (so a huge table can't make it slow). */
export type LimitedCount = {
	/**  Never more than the cap. */
	count: number,
	/**  There are more rows than `count`. */
	capped: boolean,
};

export type NewColumn = {
	source: string,
	name: string,
	/**  As SQL: `bigint`, `numeric(10,2)`, `timestamp with time zone`, `jsonb`, … */
	typeName: string,
};

export type NewTableColumn = {
	name: string,
	/**  As SQL: `text`, `bigint`, `numeric(10,2)`, `timestamp with time zone`. */
	typeName: string,
	nullable: boolean,
	defaultValue: string | null,
	/**  `GENERATED … AS IDENTITY`; the type has to be an integer type. */
	identity: ColumnIdentity | null,
	primaryKey: boolean,
	comment: string | null,
};

/**  A message from the server that is not an error (ANG-32). */
export type Notice = {
	/**  `NOTICE`, `WARNING`, `INFO`, `LOG`, `DEBUG`. */
	severity: string,
	message: string,
	detail: string | null,
	hint: string | null,
	/**  SQLSTATE, e.g. `00000`. */
	code: string,
};

/**  Text to read and edit: running it (in a query tab) changes the definition in the database. */
export type ObjectDefinition = {
	/**  What to call the query tab. */
	title: string,
	sql: string,
};

export type ObjectKind = "table" | "partitionedTable" | "foreignTable" | "view" | "materializedView" | "sequence" | "function" | "procedure" | "enumType";

export type ObjectOperation = {
	kind: "createTable",
} & CreateTable | {
	kind: "rename",
} & RenameObject | {
	kind: "truncate",
} & TruncateTable | {
	kind: "drop",
} & DropObject | {
	kind: "refreshMaterializedView",
} & RefreshMaterializedView | {
	kind: "setSequence",
} & SetSequence | {
	kind: "addEnumValue",
} & AddEnumValue | {
	kind: "createDatabase",
} & CreateDatabase | {
	kind: "dropDatabase",
} & DropDatabase | {
	kind: "createSchema",
} & CreateSchema | {
	kind: "renameSchema",
} & RenameSchema | {
	kind: "dropSchema",
} & DropSchema;

export type OnError = 
/**  The first row that can't be written stops the import and nothing is kept. */
"abort" | 
/**  Rows that can't be written are left out and listed; the rest is imported. */
"skip";

/**  Fields extracted from a `postgres://` URL, used to fill the connection form. */
export type ParsedConnectionUrl = {
	name: string,
	host: string,
	port: number,
	user: string,
	password: string | null,
	database: string,
	sslMode: SslMode,
};

/**  What to do with the saved password when saving or testing a connection. */
export type PasswordChange = 
/**  Leave the saved password as it is. */
{ kind: "keep" } | 
/**  Save this password in the Keychain. */
{ kind: "set"; value: string } | 
/**  Remove the saved password. */
{ kind: "clear" };

export type Persistence = "permanent" | 
/**  Not written to the write-ahead log: fast, and empty after a crash. */
"unlogged" | "temporary";

/**  A set of PostgreSQL client programs found on this Mac. */
export type PgTools = {
	/**  The folder with `pg_dump`, `pg_restore` and `psql`. */
	dir: string,
	/**  `17.10` */
	version: string,
	major: number,
	/**  Where it was found: `Homebrew`, `Postgres.app`, `PATH`, `Chosen folder`, … */
	source: string,
};

/**  One statement of the plan. */
export type PlannedStatement = {
	sql: string,
	/**  "alter column status": what to call it when it fails. */
	label: string,
	/**  1-based: which of the staged changes it comes from. */
	change: number,
	/**  `CONCURRENTLY`: runs after the transaction, on its own. */
	concurrent: boolean,
	/**  Throws something away: a column, an index, a constraint. */
	destructive: boolean,
};

export type PreviewRequest = {
	path: string,
	format: ImportFormat,
};

export type PrivilegeChange = {
	target: PrivilegeTarget,
	/**  `None`: PUBLIC. */
	grantee: string | null,
	privilege: string,
	/**  `true`: `GRANT`; `false`: `REVOKE`. */
	grant: boolean,
};

export type PrivilegeMatrix = {
	/**  The columns, in the order PostgreSQL lists them. */
	privileges: string[],
	owner: string,
	/**  PUBLIC first, then every role that is not predefined. */
	rows: PrivilegeRow[],
};

/**  What one grantee holds on the target. */
export type PrivilegeRow = {
	/**  `None`: PUBLIC, everybody. */
	grantee: string | null,
	superuser: boolean,
	owner: boolean,
	granted: string[],
	/**  The ones it may pass on (`WITH GRANT OPTION`). */
	grantable: string[],
};

export type PrivilegeTarget = {
	kind: PrivilegeTargetKind,
	/**  Left empty for a schema. */
	schema: string,
	/**  The schema's name, or the relation's. */
	name: string,
};

export type PrivilegeTargetKind = "schema" | 
/**  A table, view, materialized view, foreign table or partitioned table. */
"relation" | "sequence";

export type QueryExport = {
	/**  One statement that returns rows. */
	sql: string,
	/**  The table name in `INSERT` statements. `query_result` when blank. */
	name: string | null,
};

/**
 *  The result of running a script: one entry per statement that was run. After a statement
 *  fails, the ones behind it are not run, so the last entry is the error.
 */
export type QueryRun = {
	statements: StatementResult[],
	durationMs: number,
};

export type RefAction = "noAction" | "restrict" | "cascade" | "setNull" | "setDefault";

export type RefreshMaterializedView = {
	schema: string,
	name: string,
	/**  Keeps the old rows readable while it refreshes; needs a unique index on the view. */
	concurrently: boolean,
	/**  Empties it instead of filling it again (it can't be read until the next refresh). */
	withNoData: boolean,
};

export type RenameObject = {
	/**  Not `kind`: that is what tells the operations apart. */
	objectKind: ObjectKind,
	schema: string,
	name: string,
	newName: string,
};

export type RenameSchema = {
	name: string,
	newName: string,
};

export type RestoreRequest = {
	toolsDir: string | null,
	/**  A backup file or folder. */
	path: string,
	target: RestoreTarget,
	/**  Drop what is in the backup before making it again (`--clean --if-exists`). */
	clean: boolean,
	/**  Don't set who owns what (`--no-owner`). */
	noOwner: boolean,
	/**  Programs restoring at once (`-j`), for the custom and directory formats. 1..=16. */
	jobs: number,
};

export type RestoreTarget = 
/**  A database that exists. */
{ kind: "existing"; database: string } | 
/**  Make this database first. */
{ kind: "new"; database: string };

export type ResultColumn = {
	name: string,
	typeOid: number,
	/**  As Postgres prints it: `numeric(20,6)`, `text[]`. */
	typeName: string,
};

/**  One role of the server, from `pg_roles`. */
export type Role = {
	name: string,
	canLogin: boolean,
	superuser: boolean,
	createDb: boolean,
	createRole: boolean,
	inherit: boolean,
	replication: boolean,
	bypassRls: boolean,
	/**  `None`: no limit. */
	connectionLimit: number | null,
	/**  When the password stops working; `None` for never. */
	validUntil: string | null,
	/**  The roles this one is a member of. */
	memberOf: string[],
	/**  A role PostgreSQL ships with (`pg_read_all_data`, …): it can't be changed or dropped. */
	predefined: boolean,
	/**  The role the app is connected as. */
	isCurrent: boolean,
};

/**
 *  What a role may do. Written in full whenever a role is altered, so what the form shows is
 *  what the role ends up with.
 */
export type RoleAttributes = {
	canLogin: boolean,
	superuser: boolean,
	createDb: boolean,
	createRole: boolean,
	inherit: boolean,
	replication: boolean,
	bypassRls: boolean,
	connectionLimit: number | null,
	/**  `2027-01-01` or a full timestamp; `None` for never. */
	validUntil: string | null,
};

export type RoleOperation = {
	kind: "create",
} & CreateRole | {
	kind: "alter",
} & AlterRole | {
	kind: "drop",
} & DropRole;

export type RolePasswordChange = { kind: "keep" } | { kind: "set"; value: string } | 
/**  `PASSWORD NULL` */
{ kind: "clear" };

export type RowCount = {
	count: number | null,
	/**  `false`: the planner's estimate (`pg_class.reltuples`). Prefix it with `~`. */
	exact: boolean,
};

/**  A row that could not be imported, and why. */
export type RowError = {
	/**  `line 12` (CSV, one object per line) or `item 12` (an array of objects). */
	at: string,
	message: string,
};

/**  How rows of a table are told apart when editing (ANG-8 D2). */
export type RowIdentity = { kind: "primaryKey"; columns: string[] } | 
/**  A unique index whose columns are all NOT NULL. */
{ kind: "uniqueIndex"; columns: string[] } | 
/**
 *  No key: rows are found by `ctid`, which changes when a row is updated, so edits re-read
 *  the table afterwards.
 */
{ kind: "ctid" } | 
/**  Rows can't be edited; `reason` is shown to the user. */
{ kind: "readOnly"; reason: string };

/**  A new row. Columns that are not listed get their `DEFAULT`. */
export type RowInsert = {
	values: { [key in string]: CellValue },
};

export type RowPage = {
	columns: ResultColumn[],
	/**  Every cell as text, `None` for SQL `NULL`. One entry per column. */
	rows: ((string | null)[])[],
	/**  How rows of this table are told apart when editing. */
	identity: RowIdentity,
	/**  When `identity` is `ctid`: each row's `ctid`, in the same order as `rows`. Empty otherwise. */
	ctids: string[],
	/**  There are more rows after this page. */
	hasMore: boolean,
};

/**  What to read from one table. */
export type RowQuery = {
	schema: string,
	table: string,
	/**  Clamped to `1..=10000`. */
	limit: number,
	offset: number,
	/**  Without any sort the rows come in primary key / unique index order. */
	sort: SortSpec[],
	filters: Filter[],
	/**
	 *  A `WHERE` fragment typed by the user, combined with the filters by `AND`. It is SQL, not
	 *  a value: it runs inside a read-only transaction so it can't change anything.
	 */
	rawWhere: string | null,
};

/**  How a row is found again (ANG-8 D2). Must match what the server reports for the table. */
export type RowRef = 
/**  The primary key, or a NOT NULL unique index: `columns[i]` has the value `values[i]`. */
{ kind: "key"; columns: string[]; values: string[] } | { kind: "ctid"; ctid: string };

/**  New values for some cells of one existing row. */
export type RowUpdate = {
	row: RowRef,
	/**  Column name → new value. Other columns are left alone. */
	values: { [key in string]: CellValue },
};

export type SafeMode = "off" | "confirm" | "touch-id" | "read-only";

/**  A query the person kept, with a name and an optional folder. */
export type SavedQuery = {
	id: number,
	/**  `None`: usable on every connection. */
	connectionId: string | null,
	name: string,
	/**  `""` for none. */
	folder: string,
	sql: string,
	createdAt: number | null,
};

/**  What the form sends to save (a new query without an `id`, or changes to one with). */
export type SavedQueryInput = {
	id: number | null,
	connectionId: string | null,
	name: string,
	folder: string,
	sql: string,
};

export type SchemaInfo = {
	name: string,
	owner: string,
	/**  `pg_*` and `information_schema`. */
	isSystem: boolean,
};

/**  Numbers are text: a sequence can reach 9223372036854775807, which a JS number can't hold. */
export type SequenceInfo = {
	dataType: string,
	start: string,
	increment: string,
	min: string,
	max: string,
	cache: string,
	cycle: boolean,
	/**  The last value handed out; `None` while the sequence has not been used. */
	lastValue: string | null,
	/**  `schema.table.column` if a column owns it (serial, identity). */
	ownedBy: string | null,
};

/**  `setval`: the next value handed out depends on `is_called`. */
export type SetSequence = {
	schema: string,
	name: string,
	/**  A whole number, as text (a sequence can go past what a JS number holds). */
	value: string,
	/**
	 *  `true`: `value` was already handed out, so the next is the one after it. `false`: the
	 *  next value is `value` itself.
	 */
	isCalled: boolean,
};

/**  A connection as it is written in the file and shown before it is imported. */
export type SharedConnection = {
	name: string,
	host: string,
	port: number,
	user: string,
	database: string,
	sslMode: SslMode,
	color: ColorTag,
	group: string | null,
	safeMode: SafeMode,
	statementTimeoutMs?: number | null,
	ssh?: SshConfig | null,
	sslFiles?: SslFiles | null,
	/**  The connection had a password saved: the importer is asked for one. */
	needsPassword?: boolean,
	needsSshSecret?: boolean,
	needsSslKeySecret?: boolean,
	needsSshJumpSecret?: boolean,
};

export type SortDir = "asc" | "desc";

export type SortSpec = {
	column: string,
	dir: SortDir,
};

/**  What `~/.ssh/config` says about a host name: the fields of the SSH section to fill in. */
export type SshAlias = {
	/**  `HostName`, or the name that was asked about when there is none. */
	host: string,
	port: number,
	user: string | null,
	/**  The first `IdentityFile`. */
	identityFile: string | null,
	/**  The first hop of `ProxyJump`, looked up in the file the same way. */
	jump: SshAliasJump | null,
};

export type SshAliasJump = {
	host: string,
	port: number,
	user: string | null,
	identityFile: string | null,
};

export type SshAuth = 
/**  The SSH account's password (kept in the Keychain). */
{ kind: "password" } | 
/**  A private key file (its passphrase, if it has one, is kept in the Keychain). */
{ kind: "privateKey"; path: string } | 
/**  Whatever keys the running ssh-agent (`SSH_AUTH_SOCK`) holds. */
{ kind: "agent" };

/**
 *  An SSH server to tunnel through. `host`/`port` of the connection are then as the SSH server
 *  sees them (`localhost` is the SSH server itself).
 */
export type SshConfig = {
	host: string,
	port: number,
	user: string,
	auth: SshAuth,
	/**
	 *  True when the SSH password, or the key's passphrase, is saved in the Keychain.
	 *  Maintained by the backend, ignored on input.
	 */
	hasSecret?: boolean,
	/**
	 *  A server to go through to reach this one (a bastion). Missing in files saved before
	 *  ANG-49.
	 */
	jump?: SshJump | null,
};

/**
 *  The server in front of the SSH server: connected to first, then the SSH server is reached
 *  through it.
 */
export type SshJump = {
	host: string,
	port: number,
	user: string,
	auth: SshAuth,
	/**
	 *  True when the jump host's SSH password, or its key's passphrase, is saved in the Keychain.
	 *  Maintained by the backend, ignored on input.
	 */
	hasSecret?: boolean,
};

/**  What "Test SSH" found out. */
export type SshTestResult = {
	/**  `SHA256:…` of the SSH server's host key, which is in known_hosts. */
	fingerprint: string,
	keyType: string,
	/**  The SSH server could open a connection to the database's host and port. */
	reachesDatabase: boolean,
	/**  Why not, when it could not. */
	databaseProblem: string | null,
};

/**  Files for the TLS handshake. Only the paths are stored; the files are read when connecting. */
export type SslFiles = {
	/**
	 *  The root certificate (CA) the server's certificate must be signed by, as PEM. When given,
	 *  it is the only one trusted: the system's roots are not.
	 */
	rootCert: string | null,
	/**  The certificate the server may ask the client for, as PEM. */
	clientCert: string | null,
	/**  Its private key, as PEM (PKCS#8, PKCS#1 or SEC1, plain or protected by a passphrase). */
	clientKey: string | null,
	/**
	 *  True when the key's passphrase is saved in the Keychain. Maintained by the backend,
	 *  ignored on input.
	 */
	hasKeySecret?: boolean,
};

export type SslMode = "disable" | "prefer" | "require" | "verify-ca" | "verify-full";

export type StartupState = {
	/**
	 *  Open the connection that was open last time, with its tabs; `false` shows the welcome
	 *  screen.
	 */
	restoreOnLaunch: boolean,
	/**  The connection that was open when the app was last used. `None` after a disconnect. */
	lastConnectionId: string | null,
};

/**  One statement of a script and what it does. */
export type StatementClass = {
	range: TextRange,
	kind: StatementKind,
	/**  The first word in capitals, or two for `SELECT INTO` and `COPY FROM`. */
	command: string,
	/**  It could make a read-only session writable again. */
	unlocksWrites: boolean,
};

/**  What a statement does, for the safe modes (ANG-25). */
export type StatementKind = 
/**  Reads, or only changes the session. */
"read" | 
/**  Changes data. */
"write" | 
/**  Changes the schema or permissions. */
"schema";

export type StatementOutcome = 
/**  The statement returned rows (possibly none): a `SELECT`, `RETURNING`, `SHOW`, … */
{ kind: "rows"; columns: ResultColumn[]; 
/**  Every cell as text, `None` for SQL `NULL`. Booleans are `true` / `false`. */
rows: ((string | null)[])[]; 
/**  More rows existed than the cap; the rest were not read. */
truncated: boolean } | 
/**  `INSERT`, `UPDATE`, DDL, … `command` is its first word in capitals. */
{ kind: "command"; command: string; affected: number } | { kind: "error"; error: AppError; 
/**
 *  Where the server pointed, as an offset into the submitted text. `None` when it
 *  named no position.
 */
offset: number | null };

export type StatementResult = {
	/**  The statement within the submitted text. */
	range: TextRange,
	durationMs: number,
	outcome: StatementOutcome,
	/**
	 *  What the server said while running it: `RAISE NOTICE` / `WARNING`, "table does not exist,
	 *  skipping", … In the order they arrived.
	 */
	notices: Notice[],
};

export type StructureApplyResult = {
	/**  How many statements ran. */
	statements: number,
	/**
	 *  Set when a statement that runs outside the transaction failed. The transaction's changes
	 *  were saved; this one and the ones after it were not run.
	 */
	failedConcurrent: ConcurrentFailure | null,
};

export type StructureChange = {
	kind: "addColumn",
} & AddColumn | {
	kind: "alterColumn",
} & AlterColumn | {
	kind: "dropColumn",
} & DropColumn | {
	kind: "createIndex",
} & CreateIndex | {
	kind: "dropIndex",
} & DropIndex | {
	kind: "addPrimaryKey",
} & KeySpec | {
	kind: "addUnique",
} & KeySpec | {
	kind: "addCheck",
} & CheckSpec | {
	kind: "addForeignKey",
} & ForeignKeySpec | {
	kind: "dropConstraint",
} & DropConstraint;

export type StructureColumn = {
	/**  1-based position in the table. */
	position: number,
	name: string,
	/**  As Postgres prints it: `numeric(20,6)`, `character varying(100)`, `text[]`. */
	typeName: string,
	nullable: boolean,
	/**  The `DEFAULT` expression, or for a generated column the expression it is computed from. */
	defaultValue: string | null,
	identity: ColumnIdentity | null,
	generated: GeneratedKind | null,
	/**  Only when it differs from the type's own collation. */
	collation: string | null,
	comment: string | null,
	isPrimaryKey: boolean,
	foreignKeys: ForeignKeyRef[],
};

/**  What the staged changes would run, for the preview. */
export type StructurePreview = {
	statements: PlannedStatement[],
	/**  The same, as text to read: the transaction first, then what runs outside it. */
	sql: string,
};

/**
 *  Everything staged for one table. Applied in one transaction: deletes first (they free keys),
 *  then updates, then inserts.
 */
export type TableChanges = {
	updates: RowUpdate[],
	inserts: RowInsert[],
	deletes: RowRef[],
};

export type TableDescription = {
	schema: string,
	name: string,
	kind: ObjectKind,
	comment: string | null,
	columns: ColumnInfo[],
	identity: RowIdentity,
};

export type TableExport = {
	schema: string,
	table: string,
	filters: Filter[],
	/**  A `WHERE` fragment typed by the person (it runs in a read-only transaction). */
	rawWhere: string | null,
	/**  The order of the grid. Without one the rows come as the table has them. */
	sort: SortSpec[],
};

export type TableInfo = {
	owner: string,
	comment: string | null,
	persistence: Persistence,
	/**  The planner's estimate (`pg_class.reltuples`); `None` before the first `ANALYZE`. */
	rowEstimate: number | null,
	/**  Table, TOAST and indexes together. */
	totalBytes: number | null,
	/**  The table and its TOAST data, without indexes. */
	tableBytes: number | null,
	indexBytes: number | null,
	toastBytes: number | null,
	tablespace: string | null,
	/**  Table access method (`heap`). */
	accessMethod: string | null,
	/**  `RANGE (created_at)`: how a partitioned table is split. */
	partitionKey: string | null,
	/**  `FOR VALUES FROM (…) TO (…)`: which part of its parent a partition holds. */
	partitionBound: string | null,
	/**  The parent of a partition, or the tables a table inherits from. */
	parents: string[],
	/**  `schema.table` of each partition. */
	partitions: string[],
	rowSecurity: boolean,
	options: string[],
	/**  Materialized views: has it been filled? */
	populated: boolean | null,
};

export type TableRef = {
	schema: string,
	table: string,
};

export type TableStructure = {
	schema: string,
	name: string,
	kind: ObjectKind,
	info: TableInfo,
	columns: StructureColumn[],
	indexes: IndexInfo[],
	constraints: ConstraintInfo[],
	triggers: TriggerInfo[],
	/**
	 *  The statements that create this table and everything of its own: indexes, foreign keys,
	 *  triggers, comments.
	 */
	ddl: string,
	/**
	 *  What those statements need to exist first: extensions, types, sequences and the
	 *  functions that triggers, defaults and checks call. Empty when there is nothing.
	 */
	prerequisites: string,
};

/**
 *  A stretch of the submitted text. Offsets count UTF-16 code units, which is what the
 *  editor in the UI counts, so they can be used as editor positions without conversion.
 */
export type TextRange = {
	start: number,
	end: number,
};

export type ToolState = "running" | "done" | "failed" | "cancelled";

export type ToolStatus = {
	state: ToolState,
	/**  What the program printed, the last lines. */
	log: string[],
	/**  How many lines it printed in all. */
	lines: number | null,
	/**  For a backup: how big the file (or folder) is so far. */
	bytes: number | null,
	/**  The command, without anything secret, as it would be typed. */
	command: string,
	/**  What it made: the file, or the database. */
	output: string | null,
	error: AppError | null,
};

export type TriggerInfo = {
	name: string,
	/**  `BEFORE`, `AFTER` or `INSTEAD OF`. */
	timing: string,
	/**  `INSERT`, `UPDATE`, `DELETE`, `TRUNCATE`. */
	events: string[],
	/**  `FOR EACH ROW` rather than `FOR EACH STATEMENT`. */
	perRow: boolean,
	/**  `schema.function`. */
	function: string,
	state: TriggerState,
	definition: string,
};

export type TriggerState = "enabled" | "disabled" | 
/**  Fires only while replicating. */
"replica" | 
/**  Fires always, also while replicating. */
"always";

export type TruncateTable = {
	schema: string,
	name: string,
	/**  Start the sequences of its identity and serial columns over. */
	restartIdentity: boolean,
	/**  Also empty the tables that have a foreign key to this one. */
	cascade: boolean,
};
